{
  "$schema": "https://mintlify.com/docs.json",
  "name": "Superlog",
  "description": "Automate routine engineering tasks. Choose your model and harness, bring your tokens and subscriptions.",
  "theme": "luma",
  "colors": {
    "primary": "#8c8c8c",
    "light": "#232323",
    "dark": "#e1e1e1"
  },
  "favicon": "https://media.brand.dev/795f746d-3a5f-4fb9-ac75-cc1f5a0ebd65.svg",
  "logo": {
    "light": "https://media.brand.dev/36844916-a1f8-41f4-9fb4-2853fb1ecd17.svg",
    "dark": "https://media.brand.dev/36844916-a1f8-41f4-9fb4-2853fb1ecd17.svg",
    "href": "https://superlog.sh"
  },
  "navbar": {
    "links": [
      {
        "label": "GitHub",
        "href": "https://github.com/superloglabs/responder-oss"
      },
      {
        "label": "Book a demo",
        "href": "https://cal.com/superlog/yc"
      }
    ],
    "primary": {
      "type": "button",
      "label": "Get started",
      "href": "https://superlog.sh/app?signup=1"
    }
  },
  "navigation": {
    "tabs": [
      {
        "tab": "Documentation",
        "groups": [
          {
            "group": "Get started",
            "pages": [
              "index",
              "quickstart",
              "how-it-works"
            ]
          },
          {
            "group": "Automations",
            "pages": [
              "automations/overview",
              "automations/templates",
              "automations/triggers",
              "automations/connectors",
              "automations/models",
              "automations/runs"
            ]
          },
          {
            "group": "Tag mode",
            "pages": [
              "tag-mode"
            ]
          },
          {
            "group": "Assistants",
            "pages": [
              "assistants/claude"
            ]
          },
          {
            "group": "Integrations",
            "pages": [
              "integrations/overview",
              "integrations/github",
              "integrations/slack",
              "integrations/sentry",
              "integrations/datadog",
              "integrations/linear",
              "integrations/discord",
              "integrations/custom-mcp",
              "integrations/cloud",
              "integrations/more"
            ]
          },
          {
            "group": "Settings",
            "pages": [
              "settings/workspace",
              "settings/billing",
              "settings/workspace-secrets",
              "settings/api-keys",
              "security"
            ]
          },
          {
            "group": "Self-hosting",
            "pages": [
              "self-hosting/overview",
              "self-hosting/local-development",
              "self-hosting/deployment",
              "self-hosting/environment"
            ]
          }
        ]
      },
      {
        "tab": "API reference",
        "groups": [
          {
            "group": "Overview",
            "pages": [
              "api-reference/introduction",
              "api-reference/mcp"
            ]
          },
          {
            "group": "Workspace",
            "openapi": "api-reference/openapi.json",
            "pages": [
              "GET /workspace",
              "GET /members"
            ]
          },
          {
            "group": "API keys",
            "openapi": "api-reference/openapi.json",
            "pages": [
              "GET /api-keys",
              "DELETE /api-keys/{apiKeyId}"
            ]
          },
          {
            "group": "Integrations",
            "openapi": "api-reference/openapi.json",
            "pages": [
              "GET /integrations",
              "POST /integrations/refresh",
              "GET /integrations/{integrationAccountId}/sentry-environments"
            ]
          },
          {
            "group": "Automations",
            "openapi": "api-reference/openapi.json",
            "pages": [
              "GET /automations",
              "POST /automations",
              "GET /automations/{automationId}",
              "PATCH /automations/{automationId}"
            ]
          },
          {
            "group": "Runs",
            "openapi": "api-reference/openapi.json",
            "pages": [
              "GET /automations/{automationId}/runs",
              "POST /automations/{automationId}/runs",
              "GET /runs/{runId}",
              "POST /runs/{runId}/cancel",
              "POST /runs/{runId}/messages"
            ]
          },
          {
            "group": "Tag mode",
            "openapi": "api-reference/openapi.json",
            "pages": [
              "GET /tag-mode",
              "PATCH /tag-mode"
            ]
          },
          {
            "group": "Models",
            "openapi": "api-reference/openapi.json",
            "pages": [
              "GET /models",
              "GET /model-credentials",
              "POST /model-credentials",
              "POST /model-credentials/{credentialId}/rotate",
              "POST /model-credentials/{credentialId}/test",
              "GET /model-credentials/{credentialId}/models",
              "DELETE /model-credentials/{credentialId}"
            ]
          },
          {
            "group": "Secrets",
            "openapi": "api-reference/openapi.json",
            "pages": [
              "GET /secrets",
              "POST /secrets"
            ]
          }
        ]
      }
    ]
  },
  "redirects": [
    { "source": "/introduction", "destination": "/how-it-works" },
    { "source": "/deployment", "destination": "/self-hosting/deployment" },
    { "source": "/concepts/agents", "destination": "/automations/overview" },
    { "source": "/concepts/investigations", "destination": "/automations/runs" },
    { "source": "/concepts/issues", "destination": "/automations/overview" },
    { "source": "/concepts/runtime-profiles", "destination": "/self-hosting/overview" },
    { "source": "/guides/create-agent", "destination": "/automations/overview" },
    { "source": "/guides/investigate-alert", "destination": "/automations/runs" },
    { "source": "/guides/remediation", "destination": "/integrations/github" },
    { "source": "/guides/automations", "destination": "/automations/overview" },
    { "source": "/guides/workspace-secrets", "destination": "/settings/workspace-secrets" },
    { "source": "/integrations/observability", "destination": "/integrations/more" },
    { "source": "/configuration/environment", "destination": "/self-hosting/environment" },
    { "source": "/configuration/model-access", "destination": "/automations/models" },
    { "source": "/configuration/workspace", "destination": "/settings/workspace" }
  ],
  "footer": {
    "socials": {
      "github": "https://github.com/superloglabs/responder-oss",
      "x": "https://x.com/superlogYC",
      "discord": "https://discord.gg/wJ56aRh8hx"
    }
  }
}
